from pathlib import Path
import json,hashlib,datetime
out=Path('/tmp/datacare-session-context-next/migration-staged/independent')
base={'version':'server-session-ledger-context-v1','status':'unknown','mode':None,'reason':'legacy-session-uninitialized'}
legacy=json.dumps(base,separators=(',',':'))
unknown=json.dumps({**base,'reason':'vendor-authority-unresolved'},separators=(',',':'))
incomplete=json.dumps({**base,'reason':'scope-incomplete'},separators=(',',':'))
cols='ALTER TABLE public.auth_session ADD COLUMN context_epoch bigint, ADD COLUMN ledger_context jsonb, ADD COLUMN last_context_selection_id varchar(36), ADD COLUMN last_context_request_sha256 char(64), ADD COLUMN last_context_from_epoch bigint;'
receipt="last_context_selection_id='12345678-1234-4234-8234-123456789abc',last_context_request_sha256='cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc',last_context_from_epoch=1"
cases=[]
def add(id,reason,setup='',expected='failure',message=None,check=None):
 v={'id':id,'reason':reason,'setupSql':setup,'expected':expected}
 if message:v['messageIncludes']=message
 if check:v['checksSql']=check
 cases.append(v)
add('M01','Legacy rows backfill to1/legacy-unknown with receipts absent',expected='success',check=f"SELECT count(*)=2 AND bool_and(context_epoch=1 AND ledger_context='{legacy}'::jsonb AND last_context_selection_id IS NULL AND last_context_request_sha256 IS NULL AND last_context_from_epoch IS NULL) FROM public.auth_session;")
add('M02','Compatible partial columns preserve every nonNULL epoch/reason and backfill onlyNULL',cols+f" UPDATE public.auth_session SET context_epoch=7,ledger_context='{incomplete}'::jsonb WHERE tenant_id='migration-alpha';",'success',check=f"SELECT count(*)=2 AND bool_and(CASE tenant_id WHEN 'migration-alpha' THEN context_epoch=7 AND ledger_context='{incomplete}'::jsonb WHEN 'migration-beta' THEN context_epoch=1 AND ledger_context='{legacy}'::jsonb ELSE false END) FROM public.auth_session;")
add('M03','Maximum valid epoch and coherent receipt remain unchanged',cols+f" UPDATE public.auth_session SET context_epoch=9223372036854775807,ledger_context='{unknown}'::jsonb,{receipt},last_context_from_epoch=9223372036854775806 WHERE tenant_id='migration-alpha';",'success',check="SELECT context_epoch=9223372036854775807 AND last_context_from_epoch=9223372036854775806 AND last_context_selection_id='12345678-1234-4234-8234-123456789abc' FROM public.auth_session WHERE tenant_id='migration-alpha';")
# Build a valid UPDATE list once; avoid assigning from_epoch twice in M03's setup.
cases[-1]['setupSql']=cases[-1]['setupSql'].replace(',last_context_from_epoch=1,last_context_from_epoch=9223372036854775806',',last_context_from_epoch=9223372036854775806')
add('M04','Matching NOT VALID new check is validated afterNULL backfill',cols+' ALTER TABLE public.auth_session ADD CONSTRAINT auth_session_context_epoch_v1_check CHECK (context_epoch>0) NOT VALID;','success',check="SELECT convalidated FROM pg_constraint WHERE conrelid='public.auth_session'::regclass AND conname='auth_session_context_epoch_v1_check';")
add('M05','Wrong epoch type refuses without casting source text',"ALTER TABLE public.auth_session ADD COLUMN context_epoch text; UPDATE public.auth_session SET context_epoch='9223372036854775808';",message='context_epoch has an incompatible type')
add('M06','Wrong receipt width refuses rather than truncating long IDs',"ALTER TABLE public.auth_session ADD COLUMN last_context_selection_id varchar(255); UPDATE public.auth_session SET last_context_selection_id='12345678-1234-4234-8234-123456789abc-extra';",message='last_context_selection_id has an incompatible type')
add('M07','Wrong legacy column width is refused, not silently narrowed',"ALTER TABLE public.auth_session ALTER COLUMN login_name TYPE varchar(256);",message='login_name has an incompatible type')
add('M08','A wrong epoch default is rejected before backfill',"ALTER TABLE public.auth_session ADD COLUMN context_epoch bigint DEFAULT0;".replace('DEFAULT0','DEFAULT 0'),message='context_epoch has an incompatible default')
known=json.dumps({**base,'status':'resolved','mode':'A'},separators=(',',':'))
add('M09','A known-mode default is not evaluated or accepted',f"ALTER TABLE public.auth_session ADD COLUMN ledger_context jsonb DEFAULT '{known}'::jsonb;",message='ledger_context has an incompatible default')
add('M10','Weaker same-named check is refused rather than trusted',cols+' ALTER TABLE public.auth_session ADD CONSTRAINT auth_session_context_epoch_v1_check CHECK (context_epoch>=0);',message='constraint auth_session_context_epoch_v1_check is incompatible')
add('M11','Existing zero epoch is not overwritten with1',cols+' UPDATE public.auth_session SET context_epoch=0;',message='invalid non-NULL values for auth_session_context_epoch_v1_check')
extra=json.dumps({**base,'extra':'not-allowed'},separators=(',',':'))
add('M12','Ledger extra JSON key is refused',cols+f" UPDATE public.auth_session SET ledger_context='{extra}'::jsonb;",message='invalid non-NULL values for auth_session_ledger_context_v1_check')
add('M13','JSON null is not SQLNULL and must not be backfilled',cols+" UPDATE public.auth_session SET ledger_context='null'::jsonb;",message='invalid non-NULL values for auth_session_ledger_context_v1_check')
add('M14','Partial receipt cannot be repaired by inventing missing members',cols+" UPDATE public.auth_session SET context_epoch=2,last_context_selection_id='12345678-1234-4234-8234-123456789abc';",message='invalid non-NULL values for auth_session_context_receipt_v1_check')
add('M15','Receipt without current epoch refuses instead of backfilling1',cols+f' UPDATE public.auth_session SET {receipt};',message='receipt has no existing current epoch')
add('M16','Receipt from current epoch is incoherent',cols+f' UPDATE public.auth_session SET context_epoch=1,{receipt};',message='invalid non-NULL values for auth_session_context_receipt_v1_check')
add('M17','UUIDv1 receipt is outside current transport profile',cols+f' UPDATE public.auth_session SET context_epoch=2,{receipt};'+" UPDATE public.auth_session SET last_context_selection_id='12345678-1234-1234-8234-123456789abc';",message='invalid non-NULL values for auth_session_context_receipt_v1_check')
add('M18','Uppercase receipt hash is refused',cols+f' UPDATE public.auth_session SET context_epoch=2,{receipt};'+" UPDATE public.auth_session SET last_context_request_sha256='AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';",message='invalid non-NULL values for auth_session_context_receipt_v1_check')
add('M19','Missing original expiry check is an unsupported baseline',"ALTER TABLE public.auth_session DROP CONSTRAINT auth_session_expiry_check;",message='missing the existing expiry check')
add('M20','Weakened original expiry check is refused',"ALTER TABLE public.auth_session DROP CONSTRAINT auth_session_expiry_check; ALTER TABLE public.auth_session ADD CONSTRAINT auth_session_expiry_check CHECK (expires_at>=created_at);",message='expiry check differs from the required validated baseline')
add('M21','Unvalidated original expiry check is refused',"ALTER TABLE public.auth_session DROP CONSTRAINT auth_session_expiry_check; ALTER TABLE public.auth_session ADD CONSTRAINT auth_session_expiry_check CHECK (expires_at>created_at) NOT VALID;",message='expiry check differs from the required validated baseline')
add('M22','Existing user trigger must not be invoked by backfill',"CREATE FUNCTION public.fixture_session_touch() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'fixture trigger must not execute'; END$$; CREATE TRIGGER fixture_session_touch BEFORE UPDATE ON public.auth_session FOR EACH ROW EXECUTE FUNCTION public.fixture_session_touch();",message='inheritance, user triggers, or rewrite rules require separate review')
add('M23','Existing UPDATE rule requires explicit review',"CREATE RULE fixture_session_rule AS ON UPDATE TO public.auth_session DO ALSO NOTIFY fixture_session_update;",message='inheritance, user triggers, or rewrite rules require separate review')
add('M24','Inherited child cannot be implicitly changed by parent UPDATE',"CREATE TABLE public.fixture_session_child () INHERITS(public.auth_session);",message='inheritance, user triggers, or rewrite rules require separate review')
add('M25','Disabled forced RLS is not an accepted baseline',"ALTER TABLE public.auth_session NO FORCE ROW LEVEL SECURITY;",message='ordinary table with enabled, forced tenant RLS')
add('M26','A weaker tenant policy must not be trusted',"ALTER POLICY tenant_isolation ON public.auth_session USING (true) WITH CHECK (true);",message='tenant_isolation policy differs from the required baseline')
add('M27','Reordered primary key is refused without rebuilding it',"ALTER TABLE public.auth_session DROP CONSTRAINT auth_session_pkey; ALTER TABLE public.auth_session ADD CONSTRAINT auth_session_pkey PRIMARY KEY (session_id,tenant_id);",message='primary key must remain (tenant_id,session_id)')
add('M28','Absent legacy column is refused rather than recreated',"ALTER TABLE public.auth_session DROP COLUMN co_year;",message='missing legacy column co_year')
f={'kind':'session-context-migration-independent-cases/v1','scope':'Canonical historical auth_session baseline; exact staged migration in a uniquely named disposable database. No execution or mainrepo mutations.','baseline':'baseline.sql','expectedLegacyRows':2,'seededTenants':['migration-alpha','migration-beta'],'cases':cases,'requiredHarnessChecks':['Connection URL loopback/55433/approved migration owner and bootstrap database validated before CREATE DATABASE. Never print credentials.','Generated target name starts datacare_context_migration_; verify unique database owner/comment before applying or dropping. Exact SQL BEGIN/COMMIT is not rewritten.','Setup must succeed before the case is credited; migration failure must match the explicit intended rejection message.','Every failure leaves complete table/schema/default/constraint/row/raw+xmin+ctid snapshots exactly unchanged from after setup.','Success leaves all legacy business/auth values unchanged, including nullable year, microsecond times, refresh hash and revoked/expiry state; retains table/PK/index/expiry/policy/RLS/owner/ACL identity.','Success permits intentional context backfill row versions to change; rerunning successful migration must leave complete post-migration physical snapshots unchanged.','Success checksSql must output exactly one true boolean, not merely exit0.','After success, app_user sees only its bound seeded tenant under forced RLS; no role creation or runtime table mutation.','Database cleanup only occurs if generated name/owner/comment still match; preserve failing logs and never drop an unrelated database.'],'notClaimed':['No live runtime migration','No fresh authenticated session/epoch/JWT/mode/closing behavior','No arbitrary inherited or triggered schema supported','No database verification yet']}
p=out/'migration-independent-cases.json';p.write_text(json.dumps(f,indent=2)+'\n')
metadata={'preparedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceContract':'/tmp/datacare-session-context-next/implementation-contract.md','basis':'Original authoritative_scope_rbac_sessions legacy schema + approved strict context DTO + independent migration review findings; outcomes are literal, not generated by running migration/harness.','cases':len(cases),'success':sum(x['expected']=='success' for x in cases),'failure':sum(x['expected']=='failure' for x in cases),'references':[{'path':str(q),'sha256':hashlib.sha256(q.read_bytes()).hexdigest()} for q in [out/'baseline.sql',p]],'executed':False}
(out/'authorship.json').write_text(json.dumps(metadata,indent=2)+'\n');print(json.dumps(metadata,indent=2))
